import{_ as e,o as i,a,b as r}from"./app.DKoEZOcr.js";const _="/ascendc.github.io/pr/5487/assets/architecture_of_cube_compute_unit_a2a3.f4cxaLjD.png",p="/ascendc.github.io/pr/5487/assets/npu_3510_hw_arch_cube.BBj9qzyT.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"概述","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/overview/overview"},{"text":"矩阵计算单元","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_unit"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_unit.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_unit.md","lastUpdated":1788329934000}'),d={name:"api/SIMD-API/basic_api/cube_compute_ISASI/overview/cube_compute_unit.md"};function c(o,t,u,s,n,I){return i(),a("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>矩阵计算单元<span id="ZH-CN_TOPIC_0000002538071190"></span></h1><p>Cube计算单元专用于执行矩阵运算，直接访问的专用缓存如下：L0A Buffer用于存储左矩阵，L0B Buffer用于存储右矩阵，L0C Buffer则用于存储初始化累加值和矩阵计算结果。</p><div data-filter="910b,A3,950"><p>下图高亮部分展示了Cube计算单元及其直接访问的专用缓存。</p></div><div data-filter="910b,A3"><p><strong>图1</strong> <a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>矩阵计算单元架构图<span id="zh-cn_topic_0000002513373312_fig88330137205"></span><br><img src="'+_+'" alt title="矩阵计算单元架构图-A2A3"></p></div><div data-filter="950"><p><strong>图2</strong> <a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>矩阵计算单元架构图<span id="zh-cn_topic_0000002513373312_fig1082103513519"></span><br><img src="'+p+'" alt title="矩阵计算单元架构图-950"></p></div><p>矩阵计算关联的存储单元为：</p><table><thead><tr><th>Buffer类型</th><th>说明</th></tr></thead><tbody><tr><td>L0A Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的左矩阵。</td></tr><tr><td>L0B Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的右矩阵。</td></tr><tr><td>L0C Buffer</td><td>AI Core内部物理存储单元，通常用于存储矩阵计算的结果，以及矩阵累加初始化值。</td></tr><tr><td>L1 Buffer</td><td>AI Core内部物理存储单元，空间相对较大，通常用于缓存矩阵计算的输入数据。矩阵计算的输入一般需要从GM搬运到L1 Buffer，然后分别搬运到L0A Buffer和L0B Buffer。</td></tr><tr><td>Fixpipe Buffer</td><td>AI Core内部物理存储单元，通常用于存储Fixpipe搬运过程中所需的量化参数等数据。</td></tr><tr><td>BiasTable Buffer</td><td>偏置存储，AI Core内部物理存储单元，通常用于存储矩阵计算所需的Bias（偏置）数据。</td></tr></tbody></table></article></div>',1)])])}const A=e(d,[["render",c]]);export{b as __pageData,A as default};
